 words:[['relevant','connected to the task','relevant experience','প্রাসঙ্গিক'],['coordinate','organise different parts of an activity','coordinate an event','সমন্বয় করা'],['verify','check whether something is true','verify a claim','যাচাই করা'],['overstate','make something sound bigger than it is','overstate your role','বাড়িয়ে বলা']],
